-- PROPOSED, NOT EXECUTED. BCM Test only. No extension installation.
-- Filing removal regression suite; temporary fixtures roll back.
begin;
set local search_path=public;
create temporary table filing_assertions(label text,passed boolean,detail text);
grant select,insert on filing_assertions to anon,authenticated;
do $$begin execute format('grant usage on schema %I to anon,authenticated',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end$$;
create function pg_temp.ok(value boolean,label text) returns boolean language plpgsql as $$
begin insert into pg_temp.filing_assertions values(label,coalesce(value,false),null);return coalesce(value,false);end$$;
create function pg_temp.is(actual anyelement,expected anyelement,label text) returns boolean language sql as $$select pg_temp.ok(actual is not distinct from expected,label)$$;
create function pg_temp.throws_ok(command text,expected text,unused text,label text) returns boolean language plpgsql as $$
declare code text:='00000';detail text;
begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate,detail=message_text;end;
insert into pg_temp.filing_assertions values(label,code=expected,case when code<>expected then code||': '||coalesce(detail,'No error') else null end);return code=expected;end$$;
create function pg_temp.lives_ok(command text,label text) returns boolean language plpgsql as $$
declare code text:='00000';detail text;
begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate,detail=message_text;end;
insert into pg_temp.filing_assertions values(label,code='00000',detail);return code='00000';end$$;
insert into auth.users(id,email) values
('a9000000-0000-0000-0000-000000000001','filing-staff@example.test'),
('a9000000-0000-0000-0000-000000000002','filing-client@example.test');
insert into vb_private.staff_members(user_id) values('a9000000-0000-0000-0000-000000000001');
insert into public.vb_clients(id,name,client_type,contact_name,portal_enabled) values('b9000000-0000-0000-0000-000000000001','Filing fixture','business','Fixture',true);
insert into public.vb_marks(id,client_id,name,mark_type,status) values('c9000000-0000-0000-0000-000000000001','b9000000-0000-0000-0000-000000000001','FIXTURE','word','not_filed');
insert into vb_private.client_memberships(client_id,user_id) values('b9000000-0000-0000-0000-000000000001','a9000000-0000-0000-0000-000000000002');
set local role anon;
select pg_temp.throws_ok($$select public.vb_save_filing_draft(null,null,null,0,'{}')$$,'42501',null,'Anonymous save denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select pg_temp.throws_ok($$select public.vb_save_filing_draft(null,null,null,0,'{}')$$,'42501',null,'Client save denied even with MFA');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.throws_ok($$select public.vb_save_filing_draft(null,null,null,0,'{}')$$,'42501',null,'Staff without MFA denied');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select pg_temp.lives_ok($$select public.vb_save_filing_draft('b9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-000000000001',null,0,'{"mark":"FIRST"}')$$,'Staff draft saves');
select pg_temp.lives_ok($$select public.vb_save_filing_draft('b9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-000000000001',(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),1,'{"mark":"SECOND"}')$$,'Second revision saves');
select pg_temp.throws_ok($$select public.vb_save_filing_draft('b9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-000000000001',(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),1,'{}')$$,'PT409',null,'Stale save rejected');
select pg_temp.is((select count(*)::integer from public.vb_filing_revisions where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001')),2,'Prior revision retained');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),1,'transfer_approval','{}')$$,'PT409',null,'Old revision approval rejected');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness','{}')$$,'PT409',null,'Readiness without check rejected');
select pg_temp.lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'check',jsonb_build_object('input','{"mark":"SECOND"}'::jsonb,'version','prototype-2','rows',(select jsonb_agg(jsonb_build_object('id',id,'status',case when id in ('legal','support') then 'REVIEW' else 'PASS' end)) from unnest(array['supported','contacts','owner','mark','scope','basis','legal','support']) id)))$$,'Check exact saved input');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'transfer_approval',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1)))$$,'22023',null,'Unresolved attorney reviews block transfer');
select pg_temp.lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'resolution',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'issue_id',id,'kind','Reviewed','reason','Attorney reviewed fixture')) from unnest(array['legal','support']) id$$,'Attorney reasons recorded');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'PT409',null,'Manual review without transfer approval rejected');
select pg_temp.lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'transfer_approval',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1)))$$,'Reviewed check permits transfer approval');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'comparison',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'pdf_sha256','wrong'))$$,'22023',null,'Removed comparison action rejected');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1)))$$,'22023',null,'Missing manual confirmation rejected');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',false))$$,'22023',null,'False manual confirmation rejected');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed','true'::text))$$,'22023',null,'String manual confirmation rejected');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id','00000000-0000-0000-0000-000000000000'::uuid,'manual_review_confirmed',true))$$,'PT409',null,'Wrong approval rejected');
select pg_temp.lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'Manual review records without PDF');
select pg_temp.is((select count(*)::integer from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='readiness'),1,'Manual review retained in history');

select pg_temp.lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'check',jsonb_build_object('input','{"mark":"SECOND"}'::jsonb,'version','prototype-2','rows',(select jsonb_agg(jsonb_build_object('id',id,'status',case when id in ('legal','support') then 'REVIEW' else 'PASS' end)) from unnest(array['supported','contacts','owner','mark','scope','basis','legal','support']) id)))$$,'Rerun creates new check');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'22023',null,'New unresolved checklist blocks manual review');
select pg_temp.lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'resolution',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'issue_id',id,'kind','Reviewed','reason','Attorney reviewed fixture')) from unnest(array['legal','support']) id$$,'New checklist reasons recorded');
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'PT409',null,'Earlier approval cannot authorize review after new check');

select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'transfer_approval',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence asc limit 1)))$$,'PT409',null,'Earlier check cannot authorize new approval');
select pg_temp.throws_ok($$delete from public.vb_filing_revisions where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001')$$,'42501',null,'History deletion denied');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select pg_temp.throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness','{}'::jsonb)$$,'42501',null,'Client manual review denied even with MFA');
select pg_temp.is((select count(*)::integer from public.vb_filing_drafts),0,'Client cannot read drafts');
select pg_temp.is((select count(*)::integer from public.vb_filing_revisions),0,'Client cannot read revision contents');
select pg_temp.is((select count(*)::integer from public.vb_filing_reviews),0,'Client cannot read internal reviews');
reset role;
select jsonb_build_object('expected',31,'executed',count(*),'all_passed',count(*)=31 and bool_and(passed),'assertions',jsonb_agg(jsonb_build_object('label',label,'passed',passed,'detail',detail))) as filing_test_results from pg_temp.filing_assertions;
rollback;
